# Function: Run the RiboParser command for RiboParser.
# Input: Function parameters and intermediate RiboParser data objects.
# Output: Processed data objects or output files generated by module functions.

from __future__ import annotations

import importlib
import subprocess
import sys
from importlib.metadata import PackageNotFoundError
from importlib.metadata import version as package_version
from pathlib import Path


def get_package_version(package_name: str = "RiboParser") -> str:
    """
    Get RiboParser version from installed package metadata.

    Returns
    -------
    str
        Package version. Return "unknown" if package metadata is not available.
    """
    try:
        return package_version(package_name)
    except PackageNotFoundError:
        return "unknown"


def read_build_info() -> dict[str, str]:
    """
    Read build information generated before packaging or installation.

    The build info file should be:
        utils/data/_build_info.py

    Returns
    -------
    dict[str, str]
        Build information dictionary.
    """
    info = {
        "version": "unknown",
        "commit": "unknown",
        "commit_date": "unknown",
        "build_date": "unknown",
    }

    try:
        from utils.data import _build_info

        info["version"] = getattr(_build_info, "__version__", "unknown")
        info["commit"] = getattr(_build_info, "__commit__", "unknown")
        info["commit_date"] = getattr(_build_info, "__commit_date__", "unknown")
        info["build_date"] = getattr(_build_info, "__build_date__", "unknown")
    except Exception:
        pass

    return info


def run_command(command: list[str], cwd: Path | None = None) -> str:
    """
    Run a shell command safely and return stdout.

    Parameters
    ----------
    command : list[str]
        Command and arguments.
    cwd : Path | None
        Working directory.

    Returns
    -------
    str
        Standard output. Return "unknown" if command fails.
    """
    try:
        result = subprocess.run(
            command,
            cwd=str(cwd) if cwd else None,
            check=True,
            capture_output=True,
            text=True,
        )
        output = result.stdout.strip()
        return output if output else "unknown"
    except Exception:
        return "unknown"


def find_git_root(start_path: Path | None = None) -> Path | None:
    """
    Find git repository root from current file path.

    This only works when RiboParser is running from a source checkout
    or an editable installation with .git metadata available.

    Parameters
    ----------
    start_path : Path | None
        Start path for searching.

    Returns
    -------
    Path | None
        Git root path, or None if not found.
    """
    if start_path is None:
        start_path = Path(__file__).resolve()

    current = start_path if start_path.is_dir() else start_path.parent

    for parent in [current, *current.parents]:
        git_root = run_command(
            ["git", "-C", str(parent), "rev-parse", "--show-toplevel"]
        )

        if git_root != "unknown":
            return Path(git_root)

    return None


def get_git_commit() -> str:
    """
    Get latest git commit hash.

    Returns
    -------
    str
        Short commit hash, or "unknown".
    """
    git_root = find_git_root()

    if git_root is None:
        return "unknown"

    return run_command(["git", "-C", str(git_root), "rev-parse", "--short", "HEAD"])


def get_git_commit_date() -> str:
    """
    Get latest git commit date.

    Returns
    -------
    str
        Commit date in YYYY-MM-DD format, or "unknown".
    """
    git_root = find_git_root()

    if git_root is None:
        return "unknown"

    return run_command(["git", "-C", str(git_root), "log", "-1", "--format=%cs"])


def get_update_date() -> str:
    """
    Get RiboParser update date.

    Priority:
    1. Generated build metadata: utils.data._build_info.__commit_date__
    2. Current git repository latest commit date
    3. Generated build date
    4. unknown

    Returns
    -------
    str
        Update date.
    """
    build_info = read_build_info()

    if build_info["commit_date"] != "unknown":
        return build_info["commit_date"]

    git_commit_date = get_git_commit_date()

    if git_commit_date != "unknown":
        return git_commit_date

    if build_info["build_date"] != "unknown":
        return build_info["build_date"]

    return "unknown"


def get_commit() -> str:
    """
    Get RiboParser git commit.

    Priority:
    1. Generated build metadata
    2. Current git repository
    3. unknown

    Returns
    -------
    str
        Short commit hash.
    """
    build_info = read_build_info()

    if build_info["commit"] != "unknown":
        return build_info["commit"]

    return get_git_commit()


class RiboParserInfo:
    build_info = read_build_info()

    version = get_package_version()
    if version == "unknown" and build_info["version"] != "unknown":
        version = build_info["version"]

    update_date = get_update_date()
    commit = get_commit()

    citation = """
Shuchao Ren, Yinan Li, Zhipeng Zhou.
RiboParser/RiboShiny: An integrated platform for comprehensive analysis and
visualization of ribo-seq data.
Journal of Genetics and Genomics (2025)
doi:10.1016/j.jgg.2025.04.010.
"""

    required_packages = [
        "pandas",
        "polars",
        "numpy",
        "matplotlib-venn",
        "seqlogo",
        "matplotlib",
        "seaborn",
        "biopython",
        "scipy",
        "scikit-learn",
        "statsmodels",
        "pysam",
        "joblib",
    ]

    @classmethod
    def show_version(cls):
        print(f"RiboParser version: {cls.version}")
        print(f"Last update: {cls.update_date}")

        if cls.commit != "unknown":
            print(f"Git commit: {cls.commit}")

    @classmethod
    def show_citation(cls):
        print("Please cite:")
        print(cls.citation)

    @classmethod
    def check_dependencies(cls):
        missing = []

        for pkg in cls.required_packages:
            try:
                package_version(pkg)
            except PackageNotFoundError:
                missing.append(pkg)

        if missing:
            print(f"Missing dependencies: {', '.join(missing)}")
            return False

        print(cls.required_packages)
        print("All required dependencies are installed.")
        return True

    @classmethod
    def check_package_modules(cls, module_type: str = "all"):
        current_file = Path(__file__).resolve()
        root = current_file.parents[2]

        if str(root) not in sys.path:
            sys.path.insert(0, str(root))

        utils_dir = root / "utils"
        scripts_dir = root / "scripts"

        modules = {
            "ribo": [],
            "serp": [],
            "smorf": [],
            "scripts": [],
        }

        def module_name_from_path(path: Path) -> str:
            rel = path.relative_to(root)
            return ".".join(rel.with_suffix("").parts)

        def add_module(path: Path):
            if path.name.startswith("_") or path.name == "__init__.py":
                return

            mod = module_name_from_path(path)
            parts = path.relative_to(root).parts
            stem = path.stem

            if "smorf" in parts or stem.startswith("smorf_"):
                modules["smorf"].append(mod)
            elif "serp" in parts or stem.startswith("serp_"):
                modules["serp"].append(mod)
            elif "ribo" in parts or stem.startswith(("rpf_", "rna_")):
                modules["ribo"].append(mod)
            elif "scripts" in parts:
                modules["scripts"].append(mod)

        if utils_dir.exists():
            for path in utils_dir.rglob("*.py"):
                add_module(path)

        if scripts_dir.exists():
            for path in scripts_dir.rglob("*.py"):
                add_module(path)

        for key in modules:
            modules[key] = sorted(set(modules[key]))

        def try_import(module_name: str) -> bool:
            try:
                importlib.import_module(module_name)
                return True
            except Exception:
                return False

        show_keys = modules.keys() if module_type == "all" else [module_type]

        for key in show_keys:
            print(f"{key} modules:")

            if modules.get(key):
                for mod in modules[key]:
                    status = "[import OK]" if try_import(mod) else "[import FAILED]"
                    print(f" - {mod} {status}")
            else:
                print(" - (not found)")
